class Movie:
    def __init__(self, title, year):
        self.title = title
        self.year = year

    def __str__(self):
        return f"{self.title} ({self.year})"


n = int(input())
movies = []
for _ in range(n):
    title, year = input().split()
    movies.append(Movie(title, int(year)))

for movie in sorted(movies, key=lambda m: m.year):
    print(movie)
print(f"Oldest: {min(movies, key=lambda m: m.year)}")
print(f"Newest: {max(movies, key=lambda m: m.year)}")

