practice.solution:
class Employee:
    def __init__(self, name, salary):
        self.name = name
        self.salary = salary

    def __str__(self):
        return f"{self.name} {self.salary}"


n = int(input())
staff = []
for _ in range(n):
    name, salary = input().split()
    staff.append(Employee(name, int(salary)))

for employee in sorted(staff, key=lambda e: e.salary, reverse=True):
    print(employee)
top = max(staff, key=lambda e: e.salary)
print(f"Top: {top.name}")
print(f"Payroll: {sum(e.salary for e in staff)}")
